// Notes on cells in the workbook view: adding one from the menu of a cell and
// with Shift+F2, editing and deleting it, the field it is typed in, undo and
// redo, saving, and what is refused (a threaded comment, a read-only view).
//
// Positions are written out by hand from the default sizes of a sheet (header
// 72 x 22, columns 64 wide, rows 20 high). Every workbook is generated by
// code, and everything is kept within columns A to D so that a phone shows it.
import type { Page } from '@playwright/test';
import { comment, commentsXml, drawingWorkbook, vmlNote, vmlXml } from '../test/sheet-drawing-fixtures';
import { expect, test } from './helpers';

const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;
const WHITE = [255, 255, 255];
const MARK = [224, 40, 30];
const XML = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
const NS_TC = 'http://schemas.microsoft.com/office/spreadsheetml/2018/threadedcomments';

const cells = '<sheetData><row r="1"><c r="A1"><v>1</v></c></row><row r="2"><c r="B2" t="inlineStr"><is><t>veri</t></is></c></row></sheetData>';

/** B2 has a note by Ayşe, C4 one by Bora. */
const notesWorkbook = () =>
  drawingWorkbook({
    sheet: cells,
    comments: commentsXml(['Ayşe', 'Bora'], comment('B2', 0, '<t>İlk not</t>') + comment('C4', 1, '<t>Düz not</t>')),
    vml: vmlXml(vmlNote(1, 1) + vmlNote(3, 2)),
  });

const emptyWorkbook = () => drawingWorkbook({ sheet: cells });

/** B2 has a conversation, C4 a note. */
const threadedWorkbook = () =>
  drawingWorkbook({
    sheet: cells,
    comments: commentsXml(['tc={AAAA}', 'Bora'], comment('B2', 0, '<t>[Threaded comment]\n\nComment:\n    İlk ileti</t>') + comment('C4', 1, '<t>Düz not</t>')),
    vml: vmlXml(vmlNote(1, 1) + vmlNote(3, 2)),
    threaded: `${XML}<ThreadedComments xmlns="${NS_TC}"><threadedComment ref="B2" dT="2024-01-01T10:00:00.00" personId="{P1}" id="{AAAA}"><text>İlk ileti</text></threadedComment></ThreadedComments>`,
    persons: `${XML}<personList xmlns="${NS_TC}"><person displayName="Ada" id="{P1}" userId="ada" providerId="None"/></personList>`,
  });

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/view.html');
  await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountView(data, options);
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', `return ${code}`)((window as any).__view), code);

/** Colour of one canvas pixel (CSS coordinates relative to the canvas) after a forced redraw. */
function pixel(page: Page, x: number, y: number): Promise<number[]> {
  return page.evaluate(
    ([x, y]) => {
      const view = (window as any).__view;
      view.render();
      const canvas = document.querySelector('.bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      return Array.from(canvas.getContext('2d')!.getImageData(Math.round(x * dpr), Math.round(y * dpr), 1, 1).data).slice(0, 3);
    },
    [x, y],
  );
}

/** The top right corner of a cell, three pixels in: inside the mark of a note. */
const markOf = (page: Page, col: number, row: number) => pixel(page, HEADER_WIDTH + (col + 1) * COLUMN_WIDTH - 3, HEADER_HEIGHT + row * ROW_HEIGHT + 1.5);

/** The notes of the shown sheet as the model has them, where they are now: "B2 Ayşe: text". */
const notes = (page: Page) =>
  page.evaluate(() => {
    const view = (window as any).__view;
    const sheet = view.workbook.sheets[view.activeSheet];
    const layer = new (window as any).BymOffice.SheetDrawings(sheet);
    return layer
      .currentComments()
      .map((placed: any) => `${(window as any).BymOffice.cellName(placed.row, placed.col)} ${placed.comment.author ?? ''}: ${placed.comment.text}`)
      .sort();
  });

/** A right click (or long press) on a cell, as the browser reports it. */
async function openCellMenu(page: Page, col: number, row: number): Promise<void> {
  await page.evaluate(
    ([x, y]) => {
      const canvas = document.querySelector('.bym-canvas') as HTMLElement;
      const rect = canvas.getBoundingClientRect();
      canvas.dispatchEvent(new MouseEvent('contextmenu', { clientX: rect.left + x, clientY: rect.top + y, button: 2, bubbles: true, cancelable: true }));
    },
    [HEADER_WIDTH + (col + 0.5) * COLUMN_WIDTH, HEADER_HEIGHT + (row + 0.5) * ROW_HEIGHT],
  );
  await expect(page.locator('.bym-menu')).toBeVisible();
}

const item = (page: Page, name: string) => page.locator('.bym-menu').getByRole('menuitem', { name, exact: true });
const field = (page: Page) => page.locator('.bym-note-input');
const box = (page: Page) => page.locator('.bym-comment');
const live = (page: Page) => page.locator('.bym-live');
const select = (page: Page, col: number, row: number) => view(page, `view.select({ top: ${row}, left: ${col}, bottom: ${row}, right: ${col} })`);
const activeCell = (page: Page) => view(page, 'BymOffice.cellName(view.selection.active.row, view.selection.active.col)');
const focusGrid = (page: Page) => view(page, 'view.focus()');

test.describe('notes of a sheet', () => {
  test('the menu of a cell adds a note: it is typed beside the cell, applied with Ctrl+Enter, marked and shown', async ({ page }) => {
    await mount(page, await emptyWorkbook(), { author: 'Ada' });
    expect(await markOf(page, 2, 2)).toEqual(WHITE);
    await openCellMenu(page, 2, 2);
    await expect(item(page, 'Edit note')).toHaveCount(0);
    await expect(item(page, 'Delete note')).toHaveCount(0);
    await item(page, 'Add note').click();
    await expect(field(page)).toBeVisible();
    await expect(field(page)).toBeFocused();
    await expect(field(page)).toHaveAttribute('aria-label', 'Note C3');
    expect(await view(page, 'view.isEditingComment')).toBe(true);
    // Beside the cell and inside the view.
    const place = await page.evaluate(() => {
      const rect = (document.querySelector('.bym-note-edit') as HTMLElement).getBoundingClientRect();
      const host = (document.querySelector('.bym-canvas') as HTMLElement).getBoundingClientRect();
      return { left: rect.left - host.left, top: rect.top - host.top, right: rect.right - host.left, bottom: rect.bottom - host.top, width: host.width, height: host.height };
    });
    expect(place.left).toBeGreaterThanOrEqual(0);
    expect(place.top).toBeGreaterThanOrEqual(0);
    expect(place.right).toBeLessThanOrEqual(place.width);
    expect(place.bottom).toBeLessThanOrEqual(place.height);

    await page.keyboard.type('Yeni <b>not</b>');
    await page.keyboard.press('Enter');
    await page.keyboard.type('ikinci satır');
    await expect(field(page)).toHaveValue('Yeni <b>not</b>\nikinci satır');
    // Nothing is in the model until it is applied.
    expect(await notes(page)).toEqual([]);
    await page.keyboard.press('Control+Enter');
    await expect(field(page)).toHaveCount(0);
    expect(await view(page, 'view.isEditingComment')).toBe(false);
    expect(await notes(page)).toEqual(['C3 Ada: Yeni <b>not</b>\nikinci satır']);
    await expect.poll(() => markOf(page, 2, 2)).toEqual(MARK);
    // The box shows it as text, and it is said.
    await expect(box(page)).toHaveText('Ada:\nYeni <b>not</b>\nikinci satır');
    expect(await box(page).locator('b').count()).toBe(0);
    await expect(live(page)).toHaveText('C3. Comment: Ada: Yeni <b>not</b> ikinci satır');
    // The keys are back with the grid.
    await page.keyboard.press('ArrowDown');
    expect(await activeCell(page)).toBe('C4');
  });

  test('the menu edits a note, and a press elsewhere applies what was typed', async ({ page }) => {
    await mount(page, await notesWorkbook());
    await openCellMenu(page, 1, 1);
    await expect(item(page, 'Add note')).toHaveCount(0);
    await item(page, 'Edit note').click();
    await expect(field(page)).toHaveValue('İlk not');
    // The box of the note is not shown beside its own editor.
    await expect(box(page)).toHaveCount(0);
    await field(page).fill('Değişti');
    const canvas = (await page.locator('.bym-canvas').boundingBox())!;
    const elsewhere = { x: canvas.x + HEADER_WIDTH + 0.5 * COLUMN_WIDTH, y: canvas.y + HEADER_HEIGHT + 8.5 * ROW_HEIGHT };
    if (await page.evaluate(() => 'ontouchstart' in window)) await page.touchscreen.tap(elsewhere.x, elsewhere.y);
    else await page.mouse.click(elsewhere.x, elsewhere.y);
    await expect(field(page)).toHaveCount(0);
    // The author stays who it was.
    expect(await notes(page)).toEqual(['B2 Ayşe: Değişti', 'C4 Bora: Düz not']);
    expect(await activeCell(page)).toBe('A9');
  });

  test('the menu deletes a note: the mark goes, and it is said', async ({ page }) => {
    await mount(page, await notesWorkbook());
    await expect.poll(() => markOf(page, 1, 1)).toEqual(MARK);
    await openCellMenu(page, 1, 1);
    await item(page, 'Delete note').click();
    expect(await notes(page)).toEqual(['C4 Bora: Düz not']);
    await expect.poll(() => markOf(page, 1, 1)).toEqual(WHITE);
    await expect(box(page)).toHaveCount(0);
    await expect(live(page)).toHaveText('Note deleted');
    // Clearing the cell does not take a note along.
    await select(page, 2, 3);
    await view(page, 'view.clearSelection()');
    expect(await notes(page)).toEqual(['C4 Bora: Düz not']);
  });

  test('Shift+F2 adds a note to the active cell or edits the one it has; the keys of the field stay in it', async ({ page }) => {
    await mount(page, await notesWorkbook());
    await select(page, 0, 4);
    await focusGrid(page);
    await page.keyboard.press('Shift+F2');
    await expect(field(page)).toBeFocused();
    await expect(field(page)).toHaveValue('');
    // Letters, arrows, Delete and F2 are the field's: no cell is edited and the selection stays.
    await page.keyboard.type('ab');
    await page.keyboard.press('ArrowLeft');
    await page.keyboard.press('ArrowUp');
    await page.keyboard.press('Delete');
    await page.keyboard.press('F2');
    await page.keyboard.type('c');
    await page.keyboard.press('Enter');
    // "ab", left, up (to the start), Delete (takes the "a"), "c", Enter.
    await expect(field(page)).toHaveValue('c\nb');
    expect(await activeCell(page)).toBe('A5');
    expect(await view(page, 'view.isEditing')).toBe(false);
    await page.keyboard.press('Control+Enter');
    expect(await notes(page)).toEqual(['A5 Author: c\nb', 'B2 Ayşe: İlk not', 'C4 Bora: Düz not']);
    expect(await view(page, 'view.workbook.sheets[0].rows.get(4)')).toBe(undefined);

    // On a cell with a note: its text is there to edit, with the caret behind it.
    await select(page, 2, 3);
    await page.keyboard.press('Shift+F2');
    await expect(field(page)).toHaveValue('Düz not');
    await page.keyboard.type('!');
    await page.keyboard.press('Control+Enter');
    expect(await notes(page)).toEqual(['A5 Author: c\nb', 'B2 Ayşe: İlk not', 'C4 Bora: Düz not!']);
  });

  test('Escape gives up what was typed; an emptied note is deleted; an empty new note is none', async ({ page }) => {
    await mount(page, await notesWorkbook());
    await select(page, 1, 1);
    await focusGrid(page);
    await page.keyboard.press('Shift+F2');
    await field(page).fill('vazgeçilecek');
    await page.keyboard.press('Escape');
    await expect(field(page)).toHaveCount(0);
    expect(await notes(page)).toEqual(['B2 Ayşe: İlk not', 'C4 Bora: Düz not']);
    expect(await view(page, 'view.history.canUndo')).toBe(false);
    // The grid has the keys again.
    await page.keyboard.press('ArrowDown');
    expect(await activeCell(page)).toBe('B3');

    await page.keyboard.press('Shift+F2');
    await field(page).fill('   ');
    await page.keyboard.press('Control+Enter');
    await expect(field(page)).toHaveCount(0);
    expect(await notes(page)).toEqual(['B2 Ayşe: İlk not', 'C4 Bora: Düz not']);
    expect(await view(page, 'view.history.canUndo')).toBe(false);

    await page.keyboard.press('ArrowUp');
    await page.keyboard.press('Shift+F2');
    await field(page).fill('');
    await page.keyboard.press('Control+Enter');
    expect(await notes(page)).toEqual(['C4 Bora: Düz not']);
  });

  test('a key that belongs to an input method does not apply or give up the note', async ({ page }) => {
    await mount(page, await emptyWorkbook());
    await view(page, 'view.editComment(1, 1)');
    await field(page).fill('かな');
    await page.evaluate(() => {
      const input = document.querySelector('.bym-note-input') as HTMLTextAreaElement;
      input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', ctrlKey: true, isComposing: true, bubbles: true, cancelable: true }));
      input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', isComposing: true, bubbles: true, cancelable: true }));
      input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Process', keyCode: 229, bubbles: true, cancelable: true } as KeyboardEventInit));
    });
    await expect(field(page)).toBeVisible();
    await expect(field(page)).toHaveValue('かな');
    expect(await notes(page)).toEqual([]);
    await page.keyboard.press('Control+Enter');
    expect(await notes(page)).toEqual(['B2 Author: かな']);
  });

  test('each change of a note is one step that undo takes back and redo brings again', async ({ page }) => {
    await mount(page, await notesWorkbook());
    await view(page, 'view.setComment(4, 0, "eklendi")');
    await view(page, 'view.setComment(1, 1, "düzenlendi")');
    await view(page, 'view.setComment(3, 2, undefined)');
    expect(await notes(page)).toEqual(['A5 Author: eklendi', 'B2 Ayşe: düzenlendi']);
    await focusGrid(page);
    await page.keyboard.press('Control+z');
    expect(await notes(page)).toEqual(['A5 Author: eklendi', 'B2 Ayşe: düzenlendi', 'C4 Bora: Düz not']);
    await expect.poll(() => markOf(page, 2, 3)).toEqual(MARK);
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect(await notes(page)).toEqual(['B2 Ayşe: İlk not', 'C4 Bora: Düz not']);
    await expect.poll(() => markOf(page, 0, 4)).toEqual(WHITE);
    expect(await view(page, 'view.undo()')).toBe(false);
    await view(page, 'view.redo()');
    await view(page, 'view.redo()');
    await view(page, 'view.redo()');
    expect(await notes(page)).toEqual(['A5 Author: eklendi', 'B2 Ayşe: düzenlendi']);
    await expect.poll(() => markOf(page, 0, 4)).toEqual(MARK);
    // The view said that it changed, once per step.
    expect(await page.evaluate(() => (window as any).__events.filter((event: any) => event.type === 'change').length)).toBe(9);
  });

  test('saved and opened again, the notes are where they were put', async ({ page }) => {
    await mount(page, await emptyWorkbook(), { author: 'Ada & <Co>' });
    await view(page, 'view.setComment(2, 2, "satır 1\\nsatır 2 <&> \\u{1F600}")');
    await view(page, 'view.insertRows(0, 1)');
    await view(page, 'view.setComment(0, 0, "üstte")');
    expect(await notes(page)).toEqual(['A1 Ada & <Co>: üstte', 'C4 Ada & <Co>: satır 1\nsatır 2 <&> \u{1F600}']);
    const reread = await page.evaluate(async () => {
      const api = (window as any).BymOffice;
      const saved = await (window as any).__file.save();
      const workbook = await (await api.open(saved)).workbook();
      return (workbook.sheets[0].comments || []).map((item: any) => `${api.cellName(item.row, item.col)} ${item.author}: ${item.text}`).sort();
    });
    expect(reread).toEqual(['A1 Ada & <Co>: üstte', 'C4 Ada & <Co>: satır 1\nsatır 2 <&> \u{1F600}']);
  });

  test('a cell with a threaded comment offers its note commands switched off, and says why', async ({ page }) => {
    await mount(page, await threadedWorkbook());
    await openCellMenu(page, 1, 1);
    const reason = 'The comment in B2 is a threaded comment: it cannot be edited here';
    for (const name of ['Edit note', 'Delete note']) {
      await expect(item(page, name)).toHaveAttribute('aria-disabled', 'true');
      await expect(item(page, name)).toHaveAttribute('title', reason);
    }
    // Pressed all the same, an item says why and does nothing.
    await item(page, 'Delete note').click({ force: true });
    await expect.poll(() => page.evaluate(() => (window as any).__notices)).toEqual([{ message: reason, kind: 'error' }]);
    await expect(page.locator('.bym-menu')).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(page.locator('.bym-menu')).toHaveCount(0);
    expect(await notes(page)).toEqual(['B2 Ada: İlk ileti', 'C4 Bora: Düz not']);

    // Shift+F2 on it: no field, the reason.
    await select(page, 1, 1);
    await focusGrid(page);
    await page.keyboard.press('Shift+F2');
    await expect(field(page)).toHaveCount(0);
    await expect.poll(() => page.evaluate(() => (window as any).__notices.length)).toBe(2);
    // The note beside it is edited as any other.
    await select(page, 2, 3);
    await page.keyboard.press('Shift+F2');
    await field(page).fill('yanındaki');
    await page.keyboard.press('Control+Enter');
    expect(await notes(page)).toEqual(['B2 Ada: İlk ileti', 'C4 Bora: yanındaki']);
    expect(await view(page, 'view.history.canUndo')).toBe(true);
  });

  test('a read-only view has no note commands', async ({ page }) => {
    await mount(page, await notesWorkbook(), { readOnly: true });
    await openCellMenu(page, 1, 1);
    for (const name of ['Add note', 'Edit note', 'Delete note']) await expect(item(page, name)).toHaveCount(0);
    await page.keyboard.press('Escape');
    await select(page, 1, 1);
    await focusGrid(page);
    await page.keyboard.press('Shift+F2');
    await expect(field(page)).toHaveCount(0);
    expect(await view(page, 'view.editComment(1, 1)')).toBe(false);
    await view(page, 'view.setComment(1, 1, "x")');
    await view(page, 'view.setComment(1, 1, undefined)');
    expect(await notes(page)).toEqual(['B2 Ayşe: İlk not', 'C4 Bora: Düz not']);
    // The note is still shown (entered again: Escape put its box away).
    await select(page, 0, 0);
    await select(page, 1, 1);
    await expect(box(page)).toHaveText('Ayşe:\nİlk not');
    // Turning editing off while a note is typed applies it first.
    await view(page, 'view.setReadOnly(false)');
    await view(page, 'view.editComment(1, 1)');
    await field(page).fill('son');
    await view(page, 'view.setReadOnly(true)');
    await expect(field(page)).toHaveCount(0);
    expect(await notes(page)).toEqual(['B2 Ayşe: son', 'C4 Bora: Düz not']);
  });

  test('an inserted row moves the notes, new ones included', async ({ page }) => {
    await mount(page, await notesWorkbook());
    await view(page, 'view.setComment(5, 0, "yeni")');
    await expect.poll(() => markOf(page, 0, 5)).toEqual(MARK);
    await view(page, 'view.insertRows(0, 2)');
    expect(await notes(page)).toEqual(['A8 Author: yeni', 'B4 Ayşe: İlk not', 'C6 Bora: Düz not']);
    await expect.poll(() => markOf(page, 0, 7)).toEqual(MARK);
    expect(await markOf(page, 0, 5)).toEqual(WHITE);
    expect(await markOf(page, 1, 3)).toEqual(MARK);
    // The moved note is edited where it is now.
    await view(page, 'view.editComment(7, 0)');
    await expect(field(page)).toHaveValue('yeni');
    await field(page).fill('yeni yerinde');
    await page.keyboard.press('Control+Enter');
    await view(page, 'view.deleteRows(3, 1)');
    expect(await notes(page)).toEqual(['A7 Author: yeni yerinde', 'C5 Bora: Düz not']);
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    expect(await notes(page)).toEqual(['A6 Author: yeni', 'B2 Ayşe: İlk not', 'C4 Bora: Düz not']);
  });

  test('in a merged cell the note is the one of its top-left cell; showing another sheet applies a note being typed', async ({ page }) => {
    const bytes = await drawingWorkbook({ sheet: `${cells}<mergeCells count="1"><mergeCell ref="B5:C6"/></mergeCells>` });
    await mount(page, bytes);
    await view(page, 'view.insertSheet(1)');
    await view(page, 'view.setActiveSheet(0)');
    await openCellMenu(page, 2, 5);
    await item(page, 'Add note').click();
    await expect(field(page)).toHaveAttribute('aria-label', 'Note B5');
    await field(page).fill('birleşik');
    await view(page, 'view.setActiveSheet(1)');
    await expect(field(page)).toHaveCount(0);
    expect(await notes(page)).toEqual([]);
    await view(page, 'view.setActiveSheet(0)');
    expect(await notes(page)).toEqual(['B5 Author: birleşik']);
    await expect.poll(() => markOf(page, 2, 4)).toEqual(MARK);
    // From any cell of the merge.
    await view(page, 'view.setComment(5, 2, undefined)');
    expect(await notes(page)).toEqual([]);
  });

  test('the field is large enough for a finger and for text that does not make the page zoom', async ({ page }) => {
    await mount(page, await emptyWorkbook());
    await view(page, 'view.editComment(1, 1)');
    const size = await field(page).evaluate((el) => {
      const rect = el.getBoundingClientRect();
      return { width: rect.width, height: rect.height, font: parseFloat(getComputedStyle(el).fontSize), coarse: window.matchMedia('(pointer:coarse)').matches };
    });
    expect(size.height).toBeGreaterThanOrEqual(64);
    expect(size.width).toBeGreaterThanOrEqual(160);
    // iOS zooms into a field whose text is smaller than 16 px.
    if (size.coarse) expect(size.font).toBeGreaterThanOrEqual(16);
    await expect(field(page)).toHaveAttribute('maxlength', '32767');
    // Text that got in past the limit all the same is refused, and stays in the field.
    await field(page).evaluate((el) => {
      (el as HTMLTextAreaElement).value = 'x'.repeat(32768);
    });
    await page.keyboard.press('Control+Enter');
    await expect.poll(() => page.evaluate(() => (window as any).__notices)).toEqual([{ message: 'A note cannot be longer than 32767 characters', kind: 'error' }]);
    await expect(field(page)).toBeVisible();
    await expect(field(page)).toHaveAttribute('aria-invalid', 'true');
    expect(await notes(page)).toEqual([]);
    await page.keyboard.press('Escape');
    await expect(field(page)).toHaveCount(0);
  });
  test('review: a field that is opened and left without typing changes nothing, whatever the note holds', async ({ page }) => {
    // B2: runs and a carriage return; C4: a note without text.
    const bytes = await drawingWorkbook({
      sheet: cells,
      comments: commentsXml(['Ayşe'], comment('B2', 0, '<r><rPr><b/></rPr><t>Ayşe:</t></r><r><t xml:space="preserve">_x000D_\nmetin</t></r>') + comment('C4', 0, '<rPh sb="0" eb="1"><t>x</t></rPh>')),
      vml: vmlXml(vmlNote(1, 1) + vmlNote(3, 2)),
    });
    await mount(page, bytes);
    const runs = () => view(page, 'view.workbook.sheets[0].comments.map((item) => [item.text, item.runs ? item.runs.length : 0])');
    expect(await runs()).toEqual([
      ['Ayşe:\r\nmetin', 2],
      ['', 0],
    ]);
    for (const [row, col] of [
      [1, 1],
      [3, 2],
    ]) {
      // Applied with the keys, and by leaving the field.
      await view(page, `view.editComment(${row}, ${col})`);
      await expect(field(page)).toBeFocused();
      await page.keyboard.press('Control+Enter');
      await expect(field(page)).toHaveCount(0);
      await view(page, `view.editComment(${row}, ${col})`);
      await expect(field(page)).toBeFocused();
      await view(page, 'view.select({ top: 8, left: 0, bottom: 8, right: 0 })');
      await view(page, 'view.focus()');
      await expect(field(page)).toHaveCount(0);
    }
    expect(await runs()).toEqual([
      ['Ayşe:\r\nmetin', 2],
      ['', 0],
    ]);
    expect(await view(page, 'view.history.canUndo')).toBe(false);
    expect(await view(page, 'view.workbook.sheets[0].commentsModified')).toBe(undefined);
    // Typed and typed back is no change either; a real change is one.
    await view(page, 'view.editComment(1, 1)');
    await page.keyboard.type('x');
    await page.keyboard.press('Backspace');
    await page.keyboard.press('Control+Enter');
    expect(await view(page, 'view.history.canUndo')).toBe(false);
    await view(page, 'view.editComment(1, 1)');
    await page.keyboard.type('!');
    await page.keyboard.press('Control+Enter');
    expect(await runs()).toEqual([
      ['Ayşe:\nmetin!', 0],
      ['', 0],
    ]);
  });

  test('review: cells merged over a note keep it as the note of the merged cell; the menu edits it and adds no second one', async ({ page }) => {
    await mount(page, await notesWorkbook());
    // B2 (with its note) becomes an inner cell of A1:C3.
    await view(page, 'view.select({ top: 0, left: 0, bottom: 2, right: 2 })');
    await view(page, 'view.merge()');
    await openCellMenu(page, 0, 0);
    await expect(item(page, 'Add note')).toHaveCount(0);
    await item(page, 'Edit note').click();
    await expect(field(page)).toHaveValue('İlk not');
    await field(page).fill('birleşik');
    await page.keyboard.press('Control+Enter');
    expect(await notes(page)).toEqual(['B2 Ayşe: birleşik', 'C4 Bora: Düz not']);
    await openCellMenu(page, 2, 2);
    await item(page, 'Delete note').click();
    expect(await notes(page)).toEqual(['C4 Bora: Düz not']);
  });

  test('review: a sheet whose legacy drawing cannot be read offers its note commands switched off, and says why', async ({ page }) => {
    await mount(page, await drawingWorkbook({ sheet: cells, comments: commentsXml(['Ayşe'], comment('B2', 0, '<t>İlk not</t>')), vml: '' }));
    const reason = 'The notes of this sheet cannot be changed: its drawing of note boxes cannot be read';
    await openCellMenu(page, 1, 1);
    for (const name of ['Edit note', 'Delete note']) await expect(item(page, name)).toHaveAttribute('title', reason);
    await page.keyboard.press('Escape');
    await openCellMenu(page, 3, 3);
    await expect(item(page, 'Add note')).toHaveAttribute('aria-disabled', 'true');
    await expect(item(page, 'Add note')).toHaveAttribute('title', reason);
    await item(page, 'Add note').click({ force: true });
    await expect.poll(() => page.evaluate(() => (window as any).__notices)).toEqual([{ message: reason, kind: 'error' }]);
    await page.keyboard.press('Escape');
    await expect(field(page)).toHaveCount(0);
    // The rest of the sheet is edited and saved.
    await view(page, 'view.setCellInput(5, 0, "7")');
    const reread = await page.evaluate(async () => {
      const api = (window as any).BymOffice;
      const workbook = await (await api.open(await (window as any).__file.save())).workbook();
      return [workbook.sheets[0].rows.get(5).cells[0].value, workbook.sheets[0].comments.length];
    });
    expect(reread).toEqual([7, 1]);
  });
});
